SELECT COUNT(*)
  FROM emp92_sms_notice
 WHERE emp92_person_id = #{personId}
   AND emp92_sms_notice_cd = #{noticeCode}
   AND COALESCE(emp92_talk_notice_yn, 'false') = 'false'

SELECT COUNT(*)
  FROM emp92_sms_notice
 WHERE emp92_person_id = #{personId}
   AND emp92_sms_notice_cd = #{noticeCode}
   AND COALESCE(emp92_mail_notice_yn, 'true') = 'false'

